mapper.select:
SELECT * FROM (
    SELECT 
      FROM SY_AFFIRM_EMAIL EM
     WHERE EM.ACTIVITY = 0
       AND EM.AFFIRM_PERSON_ID = #{approverId, jdbcType=VARCHAR}
       AND TO_CHAR(EM.APPLY_NO) = #{applyNo, jdbcType=VARCHAR}
       AND TO_CHAR(EM.APPLY_TYPE) = #{applyType, jdbcType=VARCHAR}
       AND EM.APPLY_AFFIRM_FLAG NOT IN ('14014310', '14014309', '14014308')
       AND NOT EXISTS (SELECT 1 FROM ESS_LEAVE_APPLY_TB TB WHERE TB.APPLY_NO = EM.APPLY_NO AND TB.BATCH_YN = 2)
       AND NOT EXISTS (SELECT 1 FROM ESS_APPLY_OT OT WHERE OT.APPLY_NO = EM.APPLY_NO AND OT.BATCH_YN = 2)
     ORDER BY EM.AFFIRM_LEVEL
) WHERE ROWNUM = 1

SELECT COUNT(1)
  FROM SY_AFFIRM_EMAIL EM
 WHERE EM.AFFIRM_PERSON_ID = #{approverId, jdbcType=VARCHAR}
   AND TO_CHAR(EM.APPLY_NO) = #{applyNo, jdbcType=VARCHAR}

SELECT * FROM (
    SELECT 
      FROM SY_AFFIRM_EMAIL EM
     WHERE EM.AFFIRM_PERSON_ID = #{approverId, jdbcType=VARCHAR}
       AND TO_CHAR(EM.APPLY_NO) = #{applyNo, jdbcType=VARCHAR}
     ORDER BY EM.CREATE_DATE DESC
) WHERE ROWNUM = 1
